// The SQL behind `bun run admin:create`: the first admin, their activation link and the audit row,
// as one file so `wrangler d1 execute` applies them as one batch (docs/auth-and-security.md#flows).
// Every value is validated or generated by the caller; the email is checked against a strict
// pattern because it is placed inside a SQL literal.
export interface BootstrapAdmin {
  userId: string;
  email: string;
  tokenHash: string;
  expiresAt: number;
  now: number;
}

// There is no signed-in actor when the CLI runs, so the audit row names the tool.
export const bootstrapActor = "cli:admin-create";

export function bootstrapAdminSql({ userId, email, tokenHash, expiresAt, now }: BootstrapAdmin) {
  const timestamp = new Date(now).toISOString();
  return `
INSERT INTO "user" ("id", "name", "email", "emailVerified", "role", "createdAt", "updatedAt")
VALUES ('${userId}', '${email}', '${email}', 0, 'admin', '${timestamp}', '${timestamp}');
INSERT INTO invitations ("id", "user_id", "token_hash", "expires_at", "created_by")
VALUES ('${crypto.randomUUID()}', '${userId}', '${tokenHash}', ${expiresAt}, '${bootstrapActor}');
INSERT INTO audit_log ("id", "at", "actor_id", "action", "target_user_id", "before_json", "after_json")
VALUES ('${crypto.randomUUID()}', ${now}, '${bootstrapActor}', 'admin.create', '${userId}', NULL, '{"role":"admin"}');
`;
}
